import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { expect, test, type Download, type Page } from "@playwright/test";
import { PDFDocument } from "pdf-lib";

/** Tiny PDFs generated by e2e/fixtures/pdf/generate.mjs. */
const fixture = (name: string) => fileURLToPath(new URL(`./fixtures/pdf/${name}`, import.meta.url));

/**
 * Record every request the page makes. The PDF tools promise that files never leave the device:
 * nothing may go to another origin and nothing may be POSTed (or PUT/PATCHed) anywhere.
 */
function watchNetwork(page: Page, baseURL: string) {
  const origin = new URL(baseURL).origin;
  const offending: string[] = [];
  page.on("request", (req) => {
    const url = new URL(req.url());
    if (url.protocol === "data:") return;
    // blob: URLs carry their creator's origin ("blob:http://localhost:8787/<uuid>").
    const reqOrigin = url.protocol === "blob:" ? new URL(url.pathname).origin : url.origin;
    if (reqOrigin !== origin) offending.push(`cross-origin ${req.method()} ${req.url()}`);
    if (req.method() !== "GET" && req.method() !== "HEAD") offending.push(`${req.method()} ${req.url()}`);
  });
  return offending;
}

async function pageCount(download: Download): Promise<number> {
  const path = await download.path();
  const doc = await PDFDocument.load(await readFile(path));
  return doc.getPageCount();
}

test("/compress-pdf-for-email/ starts on the Smallest file level", async ({ page }) => {
  await page.goto("/compress-pdf-for-email/");
  const root = page.locator("[data-tool-root][data-mounted]");
  await root.locator('.tool-drop input[type="file"]').setInputFiles(fixture("five-pages.pdf"));
  await expect(root.getByRole("radio", { name: /^Smallest file/ })).toBeChecked();
  await expect(root.getByRole("radio", { name: /^Balanced/ })).not.toBeChecked();
});

test("merge two PDFs into one, entirely in the browser", async ({ page, baseURL }) => {
  const offending = watchNetwork(page, baseURL!);
  await page.goto("/merge-pdf/");
  const root = page.locator("[data-tool-root][data-mounted='true']");
  await expect(root).toBeVisible();

  await root.locator("input[type=file]").setInputFiles([fixture("two-pages.pdf"), fixture("three-pages.pdf")]);
  await expect(root.locator(".tool-item")).toHaveCount(2);

  const merge = root.getByRole("button", { name: "Merge PDFs" });
  await expect(merge).toBeEnabled();
  await merge.click();

  const downloadButton = root.getByRole("button", { name: /Download merged PDF/ });
  const [download] = await Promise.all([page.waitForEvent("download"), downloadButton.click()]);
  expect(download.suggestedFilename()).toBe("merged.pdf");
  expect(await pageCount(download)).toBe(5);

  expect(offending).toEqual([]);
});

test("split selected page ranges of a PDF into one file", async ({ page, baseURL }) => {
  const offending = watchNetwork(page, baseURL!);
  await page.goto("/split-pdf/");
  const root = page.locator("[data-tool-root][data-mounted='true']");
  await expect(root).toBeVisible();

  await root.locator("input[type=file]").setInputFiles(fixture("five-pages.pdf"));
  await expect(root.getByText(/five-pages\.pdf: 5 pages/)).toBeVisible();

  await root.getByLabel("Pages", { exact: true }).fill("1-2, 4");
  await root.getByLabel("Put all selected pages into one PDF").check();
  await root.getByRole("button", { name: "Split PDF" }).click();

  const downloadButton = root.getByRole("button", { name: "Download five-pages_pages_1-2_4.pdf" }).first();
  const [download] = await Promise.all([page.waitForEvent("download"), downloadButton.click()]);
  expect(download.suggestedFilename()).toBe("five-pages_pages_1-2_4.pdf");
  expect(await pageCount(download)).toBe(3);

  expect(offending).toEqual([]);
});
